sys_script_client.script:
function onLoad() {
    var isQuote = g_scratchpad.quoteApproval;
    if (isQuote === undefined || isQuote === null)
        isQuote = g_form.getValue('source_table') === 'sn_quote_mgmt_core_quote' ? 'true' : 'false';
    if (isQuote !== 'true')
        return;

    var allowed = g_scratchpad.quoteApprovalCanDecide;
    if (allowed === undefined || allowed === null) {
        allowed = (g_form.getValue('approver') === g_user.userID || g_user.hasRole('admin')) ? 'true' : 'false';
    }
    if (allowed === 'true')
        return;

    g_form.setActionVisible('approve', false);
    g_form.setActionVisible('reject', false);
}
